import * as runtime from "@prisma/client/runtime/client";
const config = {
    "previewFeatures": [],
    "clientVersion": "7.10.0",
    "engineVersion": "0edf323efd1d98336f3f0a68684b56f689b900d3",
    "activeProvider": "postgresql",
    "inlineSchema": "// Multi-tenant: every business table carries merchantId.\n// Money is stored in kobo (Int) to match Paystack and avoid float errors.\n\ngenerator client {\n  provider = \"prisma-client\"\n  output   = \"../src/generated/prisma\"\n}\n\ndatasource db {\n  provider = \"postgresql\"\n}\n\nenum ProductCategory {\n  CLOTHES\n  SHOES\n  JERSEY\n  ACCESSORIES\n}\n\nenum ConversationMode {\n  AI\n  HUMAN\n}\n\nenum MessageDirection {\n  INBOUND\n  OUTBOUND\n}\n\nenum MessageSender {\n  CUSTOMER\n  AI\n  OWNER\n}\n\nenum OrderStatus {\n  DRAFT\n  AWAITING_PAYMENT\n  PAID\n  FULFILLED\n  CANCELLED\n  EXPIRED\n}\n\nenum PaymentStatus {\n  PENDING\n  SUCCESS\n  FAILED\n}\n\nenum NegotiationStatus {\n  OPEN\n  AGREED\n  DECLINED\n}\n\nenum HandoffSource {\n  AI // the AI asked for the owner (complaint, refund...): resumes by itself after a timeout\n  OWNER // the owner typed in the chat from their phone: resumes after the owner goes quiet\n}\n\nenum SessionStatus {\n  DISCONNECTED\n  QR_PENDING\n  CONNECTED\n}\n\nmodel Merchant {\n  id                 String   @id @default(uuid())\n  businessName       String\n  ownerName          String\n  ownerPhone         String // WhatsApp number that receives handoff alerts, digits only e.g. 2348012345678\n  ownerEmail         String   @unique // login identity\n  alertEmail         String? // where owner alerts are emailed; falls back to ownerEmail\n  passwordHash       String\n  maxDiscountPercent Int      @default(0) // merchant-wide cap, applied on top of per-variant minPrice\n  aiEnabled          Boolean  @default(true)\n  paystackSecretEnc  String? // AES-GCM encrypted, never logged\n  receiptCounter     Int      @default(0)\n  orderCounter       Int      @default(0)\n  createdAt          DateTime @default(now())\n  updatedAt          DateTime @updatedAt\n\n  session       WhatsAppSession?\n  authItems     WaAuthItem[]\n  products      Product[]\n  customers     Customer[]\n  conversations Conversation[]\n  orders        Order[]\n}\n\nmodel WhatsAppSession {\n  merchantId String        @id\n  status     SessionStatus @default(DISCONNECTED)\n  phone      String?\n  qr         String? // latest QR string while QR_PENDING\n  updatedAt  DateTime      @updatedAt\n\n  merchant Merchant @relation(fields: [merchantId], references: [id], onDelete: Cascade)\n}\n\n// Baileys auth state (creds + signal keys) lives here so any host can restart without a new QR.\nmodel WaAuthItem {\n  merchantId String\n  key        String\n  value      String // JSON serialised with Baileys BufferJSON\n\n  merchant Merchant @relation(fields: [merchantId], references: [id], onDelete: Cascade)\n\n  @@id([merchantId, key])\n}\n\nmodel Product {\n  id          String          @id @default(uuid())\n  merchantId  String\n  name        String\n  description String?\n  category    ProductCategory\n  attributes  Json            @default(\"{}\") // e.g. jersey: {club, season, version}; shoes: {brand}\n  active      Boolean         @default(true)\n  createdAt   DateTime        @default(now())\n\n  merchant Merchant       @relation(fields: [merchantId], references: [id], onDelete: Cascade)\n  variants Variant[]\n  images   ProductImage[]\n\n  @@index([merchantId, category])\n}\n\n// Product photos. The files live in object storage (StoragePort); the database keeps only the reference.\nmodel ProductImage {\n  id         String   @id @default(uuid())\n  productId  String\n  merchantId String\n  key        String // storage key, e.g. products/<merchantId>/<id>.jpg\n  color      String? // optional: which colour this photo shows\n  position   Int      @default(0) // 0 = the main photo\n  bytes      Int\n  createdAt  DateTime @default(now())\n\n  product Product @relation(fields: [productId], references: [id], onDelete: Cascade)\n\n  @@index([productId, position])\n  @@index([merchantId])\n}\n\nmodel Variant {\n  id           String   @id @default(uuid())\n  productId    String\n  merchantId   String\n  sku          String?\n  size         String? // \"42\", \"M\", \"XL\"\n  color        String?\n  priceKobo    Int\n  minPriceKobo Int // lowest price the owner accepts. NEVER sent to the LLM.\n  stock        Int      @default(0) // physical units\n  reserved     Int      @default(0) // held for unpaid orders. available = stock - reserved\n  createdAt    DateTime @default(now())\n\n  product      Product       @relation(fields: [productId], references: [id], onDelete: Cascade)\n  orderItems   OrderItem[]\n  negotiations Negotiation[]\n\n  @@index([merchantId, productId])\n}\n\nmodel Customer {\n  id         String   @id @default(uuid())\n  merchantId String\n  phone      String // WhatsApp id digits\n  name       String?\n  address    String?\n  createdAt  DateTime @default(now())\n\n  merchant      Merchant       @relation(fields: [merchantId], references: [id], onDelete: Cascade)\n  conversations Conversation[]\n  orders        Order[]\n\n  @@unique([merchantId, phone])\n}\n\nmodel Conversation {\n  id            String           @id @default(uuid())\n  merchantId    String\n  customerId    String\n  chatId        String // gateway chat id\n  mode          ConversationMode @default(AI)\n  handoffReason String?\n  handoffBy     HandoffSource?\n  humanSince    DateTime?\n  lastMessageAt DateTime         @default(now())\n  createdAt     DateTime         @default(now())\n\n  merchant     Merchant      @relation(fields: [merchantId], references: [id], onDelete: Cascade)\n  customer     Customer      @relation(fields: [customerId], references: [id], onDelete: Cascade)\n  messages     Message[]\n  orders       Order[]\n  negotiations Negotiation[]\n\n  @@unique([merchantId, chatId])\n}\n\nmodel Message {\n  id             String           @id @default(uuid())\n  merchantId     String\n  conversationId String\n  externalId     String? // WhatsApp message id, used for dedupe\n  direction      MessageDirection\n  sender         MessageSender\n  type           String // text | audio | image | document\n  text           String?\n  meta           Json? // AI messages: { shown: [\"Name size=ref\", ...] } so the model can resolve \"that one\" next turn\n  createdAt      DateTime         @default(now())\n\n  conversation Conversation @relation(fields: [conversationId], references: [id], onDelete: Cascade)\n\n  @@unique([merchantId, externalId])\n  @@index([conversationId, createdAt])\n}\n\nmodel Negotiation {\n  id             String            @id @default(uuid())\n  conversationId String\n  variantId      String\n  rounds         Int               @default(0)\n  lastOfferKobo  Int?\n  quotedKobo     Int? // the last price WE quoted (counter / final). accept_price turns it into agreedKobo\n  agreedKobo     Int?\n  status         NegotiationStatus @default(OPEN)\n  updatedAt      DateTime          @updatedAt\n\n  conversation Conversation @relation(fields: [conversationId], references: [id], onDelete: Cascade)\n  variant      Variant      @relation(fields: [variantId], references: [id], onDelete: Cascade)\n\n  @@unique([conversationId, variantId])\n}\n\nmodel Order {\n  id              String      @id @default(uuid())\n  merchantId      String\n  customerId      String\n  conversationId  String\n  orderNumber     String // human readable per merchant, e.g. ORD-000123\n  status          OrderStatus @default(DRAFT)\n  subtotalKobo    Int         @default(0)\n  deliveryFeeKobo Int         @default(0)\n  totalKobo       Int         @default(0)\n  deliveryAddress String?\n  expiresAt       DateTime? // reservation expiry while AWAITING_PAYMENT\n  paidAt          DateTime?\n  createdAt       DateTime    @default(now())\n  updatedAt       DateTime    @updatedAt\n\n  merchant     Merchant     @relation(fields: [merchantId], references: [id], onDelete: Cascade)\n  customer     Customer     @relation(fields: [customerId], references: [id])\n  conversation Conversation @relation(fields: [conversationId], references: [id])\n  items        OrderItem[]\n  payment      Payment?\n  receipt      Receipt?\n\n  @@unique([merchantId, orderNumber])\n  @@index([merchantId, status])\n}\n\nmodel OrderItem {\n  id            String @id @default(uuid())\n  orderId       String\n  variantId     String\n  quantity      Int\n  listPriceKobo Int\n  unitPriceKobo Int // agreed price after negotiation (never below the variant floor)\n\n  order   Order   @relation(fields: [orderId], references: [id], onDelete: Cascade)\n  variant Variant @relation(fields: [variantId], references: [id])\n}\n\nmodel Payment {\n  id          String        @id @default(uuid())\n  orderId     String        @unique\n  reference   String        @unique // Paystack reference\n  status      PaymentStatus @default(PENDING)\n  amountKobo  Int\n  checkoutUrl String?\n  rawEvent    Json?\n  createdAt   DateTime      @default(now())\n  updatedAt   DateTime      @updatedAt\n\n  order Order @relation(fields: [orderId], references: [id], onDelete: Cascade)\n}\n\nmodel Receipt {\n  id        String    @id @default(uuid())\n  orderId   String    @unique\n  number    String // RCP-000123, per merchant\n  fileKey   String\n  sentAt    DateTime? // set atomically when the receipt is delivered, so it is never sent twice\n  createdAt DateTime  @default(now())\n\n  order Order @relation(fields: [orderId], references: [id], onDelete: Cascade)\n}\n\n// Idempotency for webhooks and inbound messages.\nmodel ProcessedEvent {\n  id        String   @id // e.g. \"paystack:charge.success:<reference>\"\n  createdAt DateTime @default(now())\n}\n",
    "runtimeDataModel": {
        "models": {},
        "enums": {},
        "types": {}
    },
    "parameterizationSchema": {
        "strings": [],
        "graph": ""
    }
};
